function Field() {
  const [val, setVal] = useState('');
  const inputRef = useRef(null);
  useEffect(() => {
    // прямой доступ — только через ref, для императивных задач
    inputRef.current?.focus();
  }, []);
  // value/onChange — декларативное управление DOM-узлом input
  return <input ref={inputRef} value={val} onChange={e => setVal(e.target.value)} />;
