```jsx
function Counter() {
  const [n, setN] = useState(0);
  const inc = () => {
    setN(n + 1); // старое n
    setN(n + 1); // снова старое n → в итоге +1, а не +2
    // правильно — функциональная форма:
    setN(prev => prev + 1);
    setN(prev => prev + 1); // +2
    // console.log(n); // старое значение — setState асинхронен
  };
  return <button onClick={inc}>{n}</button>;
}
```

