// Контролируемый
function ControlledForm() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');

  return (
    <form onSubmit={e => { e.preventDefault(); console.log(name, email); }}>
      <input value={name} onChange={e => setName(e.target.value)} placeholder="Name" />
      <input value={email} onChange={e => setEmail(e.target.value)} placeholder="Email" />
      <button type="submit">Submit</button>
    </form>
  );
}

// Неконтролируемый
function UncontrolledForm() {
  const nameRef = useRef();
  const emailRef = useRef();

  return (
    <form onSubmit={e => {
      e.preventDefault();
      console.log(nameRef.current.value, emailRef.current.value);
    }}>
      <input defaultValue="" ref={nameRef} placeholder="Name" />
      <input defaultValue="" ref={emailRef} placeholder="Email" />
      <button type="submit">Submit</button>
    </form>
  );
}

// Смешанный (file input — неконтролируемый)
function FileForm() {
  const [name, setName] = useState('');
  const fileRef = useRef();

  return (
    <form onSubmit={e => {
      e.preventDefault();
      const file = fileRef.current.files[0];
      console.log(name, file);
    }}>
      <input value={name} onChange={e => setName(e.target.value)} placeholder="Name" />
      <input type="file" ref={fileRef} />  {/* неконтролируемый */}
      <button type="submit">Upload</button>
    </form>
  );
}
